/**
 * Creates scopes. The main host makes one per plugin instance.
 *
 * @example
 * ```ts
 * const scope = Scope.make("example", { timeout: 3_000, log: (message, data) => console.error(message, data) })
 * ```
 */
export const Scope = {
    /**
     * Creates an open scope.
     *
     * @param name - Labels the scope in logs.
     * @param options - The deadline and the log.
     */
    make: (name, options) => create(name, options),
};
function create(name, options, detach) {
    const controller = new AbortController();
    const finalizers = new Set();
    // Finalizers that started and have not settled or been given up on.
    const running = new Map();
    // The finalizers registered before closing run on this chain, in reverse.
    const closing = { closed: false, chain: Promise.resolve() };
    const start = (finalizer) => {
        const run = Promise.resolve()
            .then(finalizer.run)
            .then(() => undefined, (cause) => options.log("scope finalizer failed", { scope: name, error: cause }))
            .finally(() => running.delete(run));
        running.set(run, finalizer.label);
        return run;
    };
    const settle = (deadline) => Promise.race([Promise.all([closing.chain, ...running.keys()]), deadline.passed])
        .then(() => undefined)
        .finally(deadline.cancel);
    const deadline = () => {
        const passed = Promise.withResolvers();
        const timer = setTimeout(() => {
            running.forEach((label, run) => {
                running.delete(run);
                if (label !== undefined)
                    options.log("scope finalizer timed out", { scope: name, finalizer: label });
            });
            passed.resolve();
        }, options.timeout);
        return { passed: passed.promise, cancel: () => clearTimeout(timer) };
    };
    const scope = {
        signal: controller.signal,
        addFinalizer(fn) {
            const finalizer = { label: fn.name || "anonymous", run: fn };
            if (closing.closed) {
                void start(finalizer);
                return () => { };
            }
            finalizers.add(finalizer);
            return () => {
                if (finalizers.delete(finalizer))
                    return fn();
            };
        },
        fork(child) {
            const finalizer = { run: () => forked.close() };
            const forked = create(`${name}/${child}`, options, () => finalizers.delete(finalizer));
            if (closing.closed)
                void forked.close();
            else
                finalizers.add(finalizer);
            return forked;
        },
        close() {
            if (closing.closed)
                return settle(deadline());
            detach?.();
            controller.abort();
            const first = deadline();
            const ordered = [...finalizers].reverse();
            finalizers.clear();
            closing.closed = true;
            closing.chain = ordered.reduce((chain, finalizer) => chain.then(() => Promise.race([start(finalizer), first.passed]).then(() => undefined)), Promise.resolve());
            return settle(first);
        },
    };
    return scope;
}
